{
  "items": [
    {
      "name": "Fintype.card_filter_piFinset_eq_of_mem",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : ι → Type u_6} [inst : DecidableEq ι] [inst_1 : Fintype ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  (s : (i : ι) → Finset (α i)) (i : ι) {a : α i},\n  a ∈ s i → {f ∈ Fintype.piFinset s | f i = a}.card = ∏ j ∈ Finset.univ.erase i, (s j).card"
    },
    {
      "name": "Cardinal.mk_setProd",
      "module_name": "Mathlib.SetTheory.Cardinal.Basic",
      "kind": "theorem",
      "type": "∀ {α β : Type u} (s : Set α) (t : Set β), Cardinal.mk ↑(s ×ˢ t) = Cardinal.mk ↑s * Cardinal.mk ↑t"
    },
    {
      "name": "Fintype.card_filter_piFinset_eq",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : ι → Type u_6} [inst : DecidableEq ι] [inst_1 : Fintype ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  (s : (i : ι) → Finset (α i)) (i : ι) (a : α i),\n  {f ∈ Fintype.piFinset s | f i = a}.card = if a ∈ s i then ∏ b ∈ Finset.univ.erase i, (s b).card else 0"
    },
    {
      "name": "Nat.card_pi",
      "module_name": "Mathlib.SetTheory.Cardinal.Finite",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : α → Type u_3} [inst : Fintype α], Nat.card ((a : α) → β a) = ∏ a, Nat.card (β a)"
    },
    {
      "name": "Finset.card_pi",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : ι → Type u_6} [inst : DecidableEq ι] (s : Finset ι) (t : (i : ι) → Finset (α i)),\n  (s.pi t).card = ∏ i ∈ s, (t i).card"
    }
  ]
}
